import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;

public class PipelineDemo {

    public interface Identifiable {
        String getId();
    }

    public static class Transaction implements Identifiable {
        final String id;
        final double amount;
        final String country;

        public Transaction(String id, double amount, String country) {
            this.id = id;
            this.amount = amount;
            this.country = country;
        }

        @Override public String getId() { return id; }
        @Override public String toString() { return id + "($" + amount + ", " + country + ")"; }
    }

    public record ValidationFailure(String itemId, String ruleName, String reason) {}

    public record PipelineResult<R>(List<R> successful, List<ValidationFailure> failures) {}

    public static class Pipeline<T extends Identifiable> {
        private final List<Predicate<? super T>> filters = new ArrayList<>();
        private final List<java.util.Map.Entry<String, Predicate<? super T>>> rules = new ArrayList<>();

        public Pipeline<T> filter(Predicate<? super T> predicate) {
            filters.add(predicate);
            return this;
        }

        public Pipeline<T> addRule(String ruleName, Predicate<? super T> rulePredicate) {
            rules.add(java.util.Map.entry(ruleName, rulePredicate));
            return this;
        }

        public <R> PipelineResult<R> process(Iterable<? extends T> items, Function<? super T, ? extends R> mapper) {
            List<R> successes = new ArrayList<>();
            List<ValidationFailure> failures = new ArrayList<>();

            for (T item : items) {
                // 1. Evaluate filters
                boolean passedFilters = true;
                for (Predicate<? super T> filter : filters) {
                    if (!filter.test(item)) {
                        passedFilters = false;
                        break;
                    }
                }
                if (!passedFilters) continue;

                // 2. Evaluate compliance rules
                boolean passedRules = true;
                for (var rule : rules) {
                    if (!rule.getValue().test(item)) {
                        failures.add(new ValidationFailure(item.getId(), rule.getKey(), "Rule violated: " + rule.getKey()));
                        passedRules = false;
                    }
                }

                if (passedRules) {
                    successes.add(mapper.apply(item));
                }
            }
            return new PipelineResult<>(List.copyOf(successes), List.copyOf(failures));
        }
    }

    public static void main(String[] args) {
        Pipeline<Transaction> pipeline = new Pipeline<>();

        // Filter out zero/negative amounts
        pipeline.filter(tx -> tx.amount > 0);

        // Rules: limit <= 10000, banned country != 'XX'
        pipeline.addRule("VELOCITY_LIMIT", tx -> tx.amount <= 10000.0);
        pipeline.addRule("SANCTIONED_COUNTRY", tx -> !"XX".equals(tx.country));

        List<Transaction> batch = Arrays.asList(
            new Transaction("TX1", 500.0, "US"),
            new Transaction("TX2", 15000.0, "UK"), // fails velocity
            new Transaction("TX3", 200.0, "XX"),   // fails sanctions
            new Transaction("TX4", -50.0, "US")     // filtered out
        );

        PipelineResult<String> result = pipeline.process(batch, tx -> "APPROVED: " + tx.id);
        System.out.println("Successful: " + result.successful());
        System.out.println("Failures: " + result.failures());
    }
}
