import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class ContravariantFilter {
    public static <T> List<T> filterList(List<T> source, Predicate<? super T> condition) {
        if (source == null || condition == null) return List.of();
        List<T> matched = new ArrayList<>();
        for (T item : source) {
            if (item != null && condition.test(item)) {
                matched.add(item);
            }
        }
        return List.copyOf(matched);
    }
}

