public class CovariantMapper {
    public static <T, R> List<R> transformAll(Iterable<? extends T> producer, Function<? super T, ? extends R> mapper) {
        if (producer == null || mapper == null) return List.of();
        List<R> result = new ArrayList<>();
        for (T item : producer) {
            if (item != null) {
                result.add(mapper.apply(item));
            }
        }
        return List.copyOf(result);
    }
}

