public class RuleEvaluator {
    public static <T> boolean evaluateAllRules(T item, List<Predicate<? super T>> rules) {
        if (rules == null || rules.isEmpty()) return true;
        for (Predicate<? super T> rule : rules) {
            if (rule != null && !rule.test(item)) {
                return false;
            }
        }
        return true;
    }
}

