import java.util.List;
import java.util.function.Predicate;

public class QuarantineRouter {
    public static <T> void partitionItems(List<T> source, Predicate<? super T> validator, List<T> passed, List<T> quarantined) {
        if (source == null || validator == null) return;
        for (T item : source) {
            if (validator.test(item)) {
                if (passed != null) passed.add(item);
            } else {
                if (quarantined != null) quarantined.add(item);
            }
        }
    }
}

