public class BoundedMaxFinder {
    public static <T extends Comparable<? super T>> T findMaxItem(Iterable<? extends T> items) {
        if (items == null) return null;
        T max = null;
        for (T item : items) {
            if (item != null) {
                if (max == null || item.compareTo(max) > 0) {
                    max = item;
                }
            }
        }
        return max;
    }
}
